(()=>{'use strict';
const L=window.PROJECT,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),now=()=>new Date().toISOString(),clone=v=>JSON.parse(JSON.stringify(v));
let state=null,teacher=new URLSearchParams(location.search).get('teacher')==='1',saveTimer,saveQueue=Promise.resolve(),saveError=false,storageMode='IndexedDB';
const classroomTeacher=new URLSearchParams(location.search).get('teacher')==='1';
let classroomTarget=null;
const classroomLocked=()=>!classroomTeacher&&!!window.ClassroomMode?.locked();
const classroomChanged=()=>window.dispatchEvent(new Event('lesson:render'));
window.LESSON={stages:L.cards.map(c=>[c.id,c.title])};
window.LessonClassroom=Object.freeze({
 info:()=>({teacher:classroomTeacher,lang:state?.student.lang||'en',page:window.TeacherPresentation?.current()||state?.current||'read',entry:!state}),
 pages:()=>[...L.cards.map(c=>c.id),...(window.TeacherPresentation?.ids()||[])],
 label:()=>window.TeacherPresentation?.current()?window.TeacherPresentation.title():state?current().title:L.cards[0].title,
 answer:id=>state?.discussions?.[id]||'',
 setAnswer:(id,v)=>{if(state&&window.TeacherPresentation?.questions[id]){(state.discussions??={})[id]=v;save(true);}},
 move:id=>{if(classroomTeacher||(!L.cards.some(c=>c.id===id)&&!window.TeacherPresentation?.ids().includes(id)))return;if(!state){classroomTarget=id;return;}if(id.startsWith('slide-')){snapshot();$('#modal').close();window.TeacherPresentation.open(id);return;}go(id,true);},
 navigate:id=>{if(state)go(id);},clearTarget:()=>{classroomTarget=null;}
});
for(const type of ['click','change'])document.addEventListener(type,e=>{if(classroomLocked()&&e.target.closest('[data-go],#cardJump,#back,#next,#importSettings,#returnEntry,#reset,#importFile,#resume,[data-action="import"]')){e.preventDefault();e.stopImmediatePropagation();if(e.target.id==='cardJump'&&state)e.target.value=state.current;}},true);
const key=()=>L.id+(teacher?'.teacher':'.student');
const db=new Promise(resolve=>{try{const r=indexedDB.open('tenby-project-lessons',1);r.onupgradeneeded=()=>r.result.createObjectStore('sessions');r.onsuccess=()=>resolve(r.result);r.onerror=()=>{storageMode='localStorage';resolve(null);};}catch{storageMode='localStorage';resolve(null);}});
async function readSaved(k){const d=await db;if(!d){try{return JSON.parse(localStorage.getItem(k)||'null');}catch{return null;}}return new Promise(resolve=>{const r=d.transaction('sessions').objectStore('sessions').get(k);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null);});}
async function writeSaved(k,s){const d=await db;if(!d){if(s)localStorage.setItem(k,JSON.stringify(s));else localStorage.removeItem(k);return;}return new Promise((resolve,reject)=>{const t=d.transaction('sessions','readwrite');if(s)t.objectStore('sessions').put(s,k);else t.objectStore('sessions').delete(k);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}
function say(t){$('#live').textContent=t;}
function save(immediate=false){if(!state)return;state.updated=now();clearTimeout(saveTimer);const status=t=>{$$('.save').forEach(x=>x.textContent=t);};status('Saving…');const write=()=>{const s=clone(state),k=key();saveQueue=saveQueue.catch(()=>{}).then(()=>writeSaved(k,s)).then(()=>{saveError=false;status('Saved on this device');}).catch(()=>{saveError=true;status('Save failed — use Backup');say('Your browser could not save. Download a backup now.');});};if(immediate)write();else saveTimer=setTimeout(write,250);}
function blank(name,cls,lang,device,editor){return {lesson:L.id,version:1,student:{name,cls,lang,device,editor},current:'read',started:now(),updated:now(),records:{},submitted:false};}
function current(){return L.cards.find(c=>c.id===state.current)||L.cards[0];}
function rec(id=current().id){return state.records[id]||(state.records[id]={values:{},history:[],checks:[],images:[],status:'Not completed'});}
function value(k,id=current().id){return rec(id).values[k]??'';}
function snapshot(id=current().id,reason='Response saved'){const r=rec(id),last=r.history.at(-1);if(Object.keys(r.values).length&&JSON.stringify(last?.values)!==JSON.stringify(r.values))r.history.push({at:now(),reason,values:clone(r.values)});save(true);}
function setStatus(status){snapshot();rec().status=status;rec().statusAt=now();save(true);progress();$('#cardStatus').textContent=status;say(status==='Completed'?'Task recorded as completed. Your teacher will review the evidence.':status);}
function titleEditor(){return {blocks:'MakeCode Blocks',make:'MakeCode Python',micro:'micro:bit MicroPython'}[state.student.editor];}
function editorURL(){return state.student.editor==='micro'?'https://python.microbit.org/':'https://makecode.microbit.org/';}
const MOBILE_APPS={ipad:{store:'https://apps.apple.com/app/micro-bit/id1092687276',name:'App Store'},android:{store:'https://play.google.com/store/apps/details?id=com.samsung.microbit',name:'Google Play'}};
function editorLink(){const app=MOBILE_APPS[state.student.device];if(app)return `<div class="mobile-editor"><a class="button editor-link" href="${app.store}" target="_blank" rel="noopener noreferrer">Open / get micro:bit via ${app.name} ↗</a><p><b>Already installed?</b> Open micro:bit from your device’s app icon, or tap <b>Open</b> on its store page. Otherwise ask permission to install it.</p><p>In the app, choose <b>Create Code</b>, then open your badge in MakeCode. ${state.student.editor==='make'?'Choose Python in MakeCode’s language menu.':'Choose Blocks.'} Switch back to this lesson to record your results.</p><small>This button opens the official store listing, not browser MakeCode. Your device controls whether the store app opens. If installation is restricted, ask your teacher—do not change school settings.</small></div>`;return `<a class="button editor-link" href="${editorURL()}" target="_blank" rel="noopener noreferrer">Open ${titleEditor()} ↗</a><small>Code in the editor tab. Return here to record your test.</small>`;}
function field(label,id,prompt='',type='textarea',val=value(id)){return `<label for="${id}">${esc(label)}${prompt?`<small>${esc(prompt)}</small>`:''}</label>${type==='textarea'?`<textarea id="${id}" data-field="${id}" maxlength="12000" placeholder="${esc(prompt)}">${esc(val)}</textarea>`:`<input id="${id}" data-field="${id}" value="${esc(val)}" maxlength="250">`}`;}
function choice(id,label,opts){return `<fieldset><legend>${esc(label)}</legend>${opts.map(o=>`<label class="option"><input type="radio" name="${id}" data-field="${id}" value="${esc(o)}" ${value(id)===o?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`;}
function check(id,label){return `<label class="option"><input type="checkbox" data-field="${id}" ${value(id)===true?'checked':''}><span>${esc(label)}</span></label>`;}
function fields(c){return (c.fields||[]).map(f=>field(f[1],f[0],f[2])).join('');}
function picture(file,alt,caption){return `<button class="image-button" data-image="${file}" aria-label="Enlarge: ${esc(alt)}"><img src="assets/images/${file}" alt="${esc(alt)}"></button><p class="caption">${esc(caption)} · Select to enlarge</p>`;}
function codePanel(source,label='Reference code'){if(label.includes('MakeCode Blocks'))return '<p class="note">Build the blocks shown above in MakeCode. The READY branch plays High C (523 Hz); the CHECK branch plays Middle C (262 Hz). Use a quarter beat for each.</p>';return `<div class="code-panel"><h3>${label}</h3><pre class="code">${esc(source)}</pre><button data-copy="${encodeURIComponent(source)}">Copy this code</button></div>`;}
function codeSample(score=4,op='>=',sound=false){return L.code(state.student.editor,score,op,sound);}
function decision(op='>='){const out=state.student.editor==='micro'?'display.scroll':'basic.show_string';return `if ready_points ${op} 5:\n    ${out}("READY")\nelse:\n    ${out}("CHECK")`;}
function decisionView(op='>=',label='Decision inside Button B'){return state.student.editor==='blocks'?`<h3>${label}</h3>${picture(op==='>'?'makecode-excludes-equality.png':'makecode-button-b-decision.png','Button B comparison '+op+' 5, READY when true and CHECK otherwise','Actual MakeCode blocks: compare the operator carefully')}`:codePanel(decision(op),label);}
function model(){return `<section class="model"><p class="section-label">Explore the rule · teaching model</p><label for="modelPoints">Readiness points</label><input id="modelPoints" type="number" data-field="modelPoints" min="0" max="99" step="1" value="${esc(value('modelPoints')||'4')}"><button id="modelRun">Press Button B</button><div id="modelOutput" class="result" aria-live="polite">${esc(value('modelOutput')||'Press B to check.')}</div><small>This model illustrates the rule. It does not run or verify your code.</small></section>`;}
function questions(c){if(!c.questions)return '';return c.questions.map((q,i)=>{const latest=[...rec().checks].reverse().find(x=>x.kind==='quiz');const feedback=latest?.results?.[i];return `<section class="quiz-item">${choice('q'+i,q.label,q.options)}<div class="feedback ${feedback?.correct?'good':'improve'}" id="qFeedback${i}" role="status">${feedback?esc(feedback.message):''}</div></section>`;}).join('')+'<button id="checkQuiz" class="primary">Check these answers</button><p class="caption">Feedback helps you improve. You can continue even if you need support.</p>';}
function support(stage){const lang=L.languages[state.student.lang];return !lang||state.student.lang==='en'?'':`<div class="support" lang="${state.student.lang==='zh'?'zh-Hans':state.student.lang}"><b>${esc(lang.label)}</b><p>${esc(lang[stage]||lang.intro)}</p><p>${esc(lang.frame)}</p></div>`;}
function ksu(after=false){const labels={K:'Knowledge',S:'Skills',U:'Understanding'},opts=after?['Independently','With a prompt','Need help']:['I know this confidently','I am beginning to know this','This is new to me'];return `<div class="confidence">${['K','S','U'].map(k=>`<section><h3>${labels[k]}</h3><p>${esc(L.goals[k])}</p>${after?`<p class="caption">My starting point: ${esc(value(k,'baseline')||'Not recorded')}</p>`:''}${choice(k,after?'What can I do now?':'My starting point',opts)}${after?choice(k+'Phase','My learning phase',['New learning / good struggle','Consolidating','Treading water','Drowning / need help']):''}</section>`).join('')}</div>`;}
function placement(){const ed=state.student.editor;return ed==='blocks'?'<ol><li>Open <b>Input</b>. Drag <b>on button A pressed</b> into empty workspace and change A to <b>B</b>.</li><li>Open <b>Logic</b>. Put the <b>if / else</b> block inside that B event.</li><li>Place a comparison in the condition. Put <b>ready_points</b> on the left, choose <b>≥</b>, and put <b>5</b> on the right.</li><li>From <b>Basic</b>, put <b>show string READY</b> in the first branch and <b>show string CHECK</b> in else.</li></ol>':ed==='make'?'<ol><li>In MakeCode, use the language dropdown beside JavaScript and choose <b>Python</b>.</li><li>Add <code>ready_points = 4</code> at the top level, outside every function.</li><li>Add the <code>def on_button_pressed_b():</code> function below the existing A function. Indent its condition by four spaces and branch outputs by eight.</li><li>Keep the final <code>input.on_button_pressed(...)</code> registration outside the function with no indentation. Do not create two B handlers.</li></ol>':'<ol><li>Use the <b>micro:bit Python editor</b>, not MakeCode Python.</li><li>Put <code>ready_points = 4</code> above the existing <code>while True:</code> loop.</li><li>Inside that same loop, add <code>if button_b.was_pressed():</code>, aligned with the existing A check.</li><li>Put the readiness condition inside the B check. Indent its outputs one level further. Do not add a second infinite loop.</li></ol>';}
function sampleActions(){return `<div class="actions">${editorLink()}<button data-sample="A">Download sample A</button><button data-sample="B">Download sample B</button></div><p class="note">Samples are source files, not files to flash directly onto a micro:bit. ${state.student.editor==='blocks'?'Download the text file, open it, copy its JavaScript into a NEW MakeCode project’s JavaScript editor, then choose Blocks.':state.student.editor==='make'?'Open a NEW MakeCode project, choose Python, then paste the downloaded source into that editor. Do not use this in MicroPython.':'Open the downloaded .py file in the micro:bit Python editor, or paste it into a new project.'} Keep your own badge project separate.</p>`;}
function evidence(){return `<div class="upload"><h3>Evidence, without a photo barrier</h3><p>Upload or paste a screenshot while this card is open. A teacher demonstration is also valid. Images stay in this browser and your backup.</p><label for="evidenceFile">Choose PNG, JPEG or WebP (up to 12 MB)</label><input id="evidenceFile" type="file" accept="image/png,image/jpeg,image/webp"><button id="pasteImage">Paste a screenshot</button><small>Or use Ctrl+V / Command+V. On iPad, use Choose File if clipboard access is unavailable. Maximum three images on this card.</small><div class="evidence-grid">${rec().images.map((im,i)=>`<div><img src="${im.data}" alt="Student evidence ${i+1}"><label>Caption<input data-caption="${i}" value="${esc(im.caption)}" maxlength="250"></label><button data-remove="${i}">Remove image ${i+1}</button></div>`).join('')}</div></div>`;}
function transferGuide(){return state.student.device!=='laptop'?'<div class="rule"><b>Tablet route: MakeCode inside the micro:bit app</b><ol><li>Save your MakeCode project. Use the school-approved micro:bit app for Bluetooth pairing and transfer.</li><li>Follow the app’s pairing instructions with your own numbered micro:bit. Ask your teacher if Bluetooth or the app is restricted.</li><li>Wait for transfer to finish, then test the welcome, A and B on the real device.</li></ol><p>This lesson uses MakeCode inside the tablet app, not the separate MicroPython editor. If transfer is blocked, keep simulator evidence and request a teacher laptop. Do not change your device’s security settings.</p></div>':'<div class="rule"><b>Laptop route</b><ol><li>Connect using a USB data cable. Hold the connector, not the wire. Do not force the micro USB port.</li><li>In MakeCode choose Download. In MicroPython choose Send to micro:bit. Follow the editor’s pairing prompts in a supported browser, or copy the downloaded .hex file onto the MICROBIT drive.</li><li>Wait for transfer to finish. Test the physical buttons. Changing the editor code alone does not update the device: transfer again after each change.</li></ol></div>';}
function extensions(){const level=Number(value('level')||1);let body='';if(level===1)body='<h2>Level 1 · New target</h2><p>The next activity needs eight preparation points. Change the threshold to eight and test 7, 8 and 9. Keep your two outputs clear.</p><p><b>Explain:</b> Which value proves that equality works?</p>';if(level===2)body='<h2>Level 2 · Boundary detective</h2><p>In a copy, deliberately change <code>>= 5</code> to <code>> 5</code>. Find a value that exposes the error. Explain why testing six does not reveal it. Fix the comparison and retest.</p><p><b>Keep your working original safe.</b> This task is about finding a revealing test, not adding more code.</p>';if(level===3)body=`<h2>Level 3 · Give the badge a voice</h2><p>Add a short high tone to the READY branch and a lower tone to CHECK. Keep both text messages so the meaning does not depend on hearing.</p><ol><li>Save a copy called SoundBadge.</li><li>${state.student.editor==='blocks'?'Open Music. Put a short play tone block after each show string, inside its branch. Use 523 Hz and 262 Hz.':state.student.editor==='micro'?'Add import music at the top. Put music.pitch(523, 200) after READY and music.pitch(262, 200) after CHECK, with matching indentation.':'Put music.play_tone(523, music.beat(BeatFraction.QUARTER)) after READY. Use 262 for CHECK, with matching indentation.'}</li><li>Test both branches. With permission, swap the tones for two short melodies of your own.</li></ol>${picture('makecode-sound-decision.png','MakeCode decision with a short tone in each branch','Sound extension: both tones belong inside the decision')}${codePanel(codeSample(4,'>=',true),titleEditor()+' sound reference')}<p class="warning">Ask before enabling sound. Use low volume. A micro:bit V2 has a built-in speaker; a V1 needs a teacher-approved external sound device. A silent simulator or LED-only version is acceptable. Grove kit wiring depends on the exact kit: ask the teacher for its approved guide before connecting anything. House points, if used, are awarded by the teacher, not this app.</p>`;return `<div class="actions">${[1,2,3].map(n=>`<button data-level="${n}" ${level===n?'aria-pressed="true" class="primary"':'aria-pressed="false"'}>Level ${n}${n===3?' · Music':''}</button>`).join('')}<button data-go="pitstop">Move to Learning Pit Stop</button></div>${body}<div class="actions">${editorLink()}</div>${field('My result for level '+level,'level'+level+'Result','I changed ___. I tested ___. The result was ___.')}${check('level'+level+'Done','I tested this challenge and recorded my result.')}`;}
function renderCard(c){let h='';switch(c.type){
case 'intro':h=`<div class="split"><div><h2>Find the decision</h2><p><b>Blocks:</b> open <b>Logic</b>, then find <b>if / else</b>. The condition selects one of its two branches.</p><p><b>Python:</b> write <code>if condition:</code> and <code>else:</code>. Indentation groups each branch. Device display commands depend on your editor.</p><div class="rule"><b>The rule</b><br>ready_points ≥ 5: READY<br>Otherwise: CHECK</div></div><div>${picture('makecode-logic-toolbox.png','Logic toolbox showing if, if/else and comparisons','Actual MakeCode toolbox')}</div></div>${state.student.editor==='blocks'?'':codePanel(state.student.editor==='micro'?'if ready_points >= 5:\n    display.scroll("READY")\nelse:\n    display.scroll("CHECK")':'if ready_points >= 5:\n    basic.show_string("READY")\nelse:\n    basic.show_string("CHECK")','The decision inside the B response')}${check('read','I have read the brief and looked at the example.')}`;break;
case 'quiz':h=questions(c)+fields(c);break;
case 'predict':h=`<p class="rule">For both samples, set <b>ready_points = 5</b>, restart, then press B. Only the comparison is different.</p><div class="split"><div>${decisionView('>=','Sample A · includes equality')}${field(c.fields[0][1],c.fields[0][0],c.fields[0][2])}${field(c.fields[2][1],c.fields[2][0],c.fields[2][2])}</div><div>${decisionView('>','Sample B · excludes equality')}${field(c.fields[1][1],c.fields[1][0],c.fields[1][2])}${field(c.fields[3][1],c.fields[3][0],c.fields[3][2])}</div></div>${sampleActions()}<button id="checkPredictions">Compare my predictions</button><div id="taskFeedback" class="feedback" role="status"></div>`;break;
case 'baseline':h=`<p class="definition">“${L.definition}”</p>${ksu()}${fields(c)}`;break;
case 'brief':h=`<div class="split"><div>${picture('makecode-worked-badge.png','Startup heart and points variable, Button A initials, Button B readiness check','A full worked example; adapt the presentation, keep the rule')}</div><div>${model()}<p><b>Input:</b> press B.<br><b>Process:</b> compare the stored points with five.<br><b>Output:</b> READY or CHECK.</p></div></div>${questions(c)}`;break;
case 'setup':h=`<div class="actions">${editorLink()}<button data-action="settings">Change device or editor</button></div><ol><li>Open your existing Smart Badge in your chosen app or editor.</li><li>Save a separate Week 5 copy before changing it. Keep your previous working version.</li><li>Run the copy. Check the welcome display and Button A still work.</li><li>Record the new project name below, then continue to add Button B.</li></ol>${fields(c)}${check('savedCopy','I saved a new version before editing.')}${check('originalChecked','I checked my original welcome and Button A response.')}<details><summary>My previous project is missing</summary><p>Tell your teacher. Use a new recovery project with the worked example. Do not pretend it is your recovered original. Replace AB with your own initials.</p><button data-sample="recovery">Download recovery source</button>${sampleActions()}</details>`;break;
case 'build':h=`<div class="actions">${editorLink()}</div><div class="split"><div>${placement()}${check('variableAdded','I set ready_points to 4 at startup.')}${check('decisionAdded','I added the B decision and kept the A response.')}</div><div>${decisionView()}${state.student.editor==='blocks'?'':`<details><summary>Full Python example for context</summary>${codePanel(codeSample(),titleEditor()+' full reference')}<p>Merge the B part into your badge. Preserve your personalised work.</p></details>`}</div></div>${fields(c)}`;break;
case 'personalise':h=`<p class="rule">Keep the rule at five. Choose two outputs that are clearly different. Avoid ambiguous messages such as “OK” for both outcomes.</p>${fields(c)}${check('bothPredicted','I can predict my chosen outputs below and at five.')}`;break;
case 'testingRead':h=`<div class="split"><div><h2>What does each test tell you?</h2><ul><li><b>4:</b> does the not-ready branch run?</li><li><b>5:</b> is equality included?</li><li><b>6:</b> does a value above the threshold work?</li></ul><p>A simulation is useful evidence. Test on hardware too when it is available. The app cannot automatically verify a physical demonstration.</p></div><div>${model()}</div></div>${check('testReading','I understand why I need more than one test.')}`;break;
case 'tests':h=`<div class="actions">${editorLink()}</div><p>After each code change, <b>restart the simulator, then press B</b>. For a physical test, transfer the changed program again.</p><div class="table-wrap"><table><thead><tr><th>Points</th><th>Expected</th><th>Actual result</th></tr></thead><tbody>${[4,5,6].map(n=>`<tr><th>${n}</th><td>${esc(n<5?(value('checkMessage','personalise')||'CHECK'):(value('readyMessage','personalise')||'READY'))}</td><td><label class="sr" for="actual${n}">Actual output at ${n}</label><input id="actual${n}" data-field="actual${n}" value="${esc(value('actual'+n))}" maxlength="250"></td></tr>`).join('')}</tbody></table></div><button id="checkTests">Review my test record</button><div id="taskFeedback" class="feedback"></div>${choice('testEnvironment','Where did I run these tests?',['Simulator','Physical micro:bit','Both','Not yet tested'])}${check('welcomeWorks','The welcome display still works.')}${check('aWorks','The original Button A response still works.')}`;break;
case 'feedback':h=fields(c)+`<p class="note">If your program already works, improve the clarity of a message or the readability of the code. Do not invent a mistake. If you are waiting for help, record the issue honestly.</p>`;break;
case 'transfer':h=transferGuide()+`<p><a href="https://microbit.org/get-started/user-guide/transfer-code-to-the-microbit/" target="_blank" rel="noopener noreferrer">Official transfer guide ↗</a></p>${choice('physical','Physical test status',['Transferred and tested','Teacher saw my demonstration','Simulator only; transfer pending','I need connection help'])}`+fields(c)+evidence();break;
case 'extension':h=extensions();break;
case 'pitstop':h=`<p class="definition">“${L.definition}”</p><p><b>New learning:</b> this is new and I am making progress. <b>Consolidating:</b> I am using earlier learning more confidently. <b>Treading water:</b> I need more challenge. <b>Drowning:</b> I need help to take the next step.</p>${ksu(true)}${fields(c)}`;break;
case 'review':h=`<div class="actions"><button data-action="pdf" class="primary">Download my project PDF</button><button data-action="print">Print / Save as PDF</button><button data-action="backup">Backup my work</button></div><p class="note">Open the downloaded PDF and check it. Then upload it to <b>Week 5 Project</b> in Teams, or the exact assignment title your teacher identifies.</p>${reportHTML()}${state.submitted?'<div class="finish"><h2>Thank you for submitting.</h2><p>Your confirmation is recorded. Ask your teacher to demonstrate a challenge or quietly revisit your extension. This app cannot verify Teams submission.</p><button data-go="extension">Return to a challenge</button></div>':''}`;break;
}return h;}
async function landing(message=''){classroomChanged();const existing=await readSaved(key());$('#app').innerHTML=`<main id="main" class="landing"><section><p class="brand-mark"><span class="mark">CS</span>TENBY · YEAR 8</p><span class="chip">Week 5 Project · 60 minutes</span><h1>Ready<br>or not?</h1><p class="lede">Give your Smart Badge a decision.<br>Test it. Improve it. Explain it.</p><h2>WAGBA</h2><p>${esc(L.goals.wagba)}</p><p class="definition"><b>Our Definition of Learning</b><br>“${L.definition}”</p></section><section class="entry"><p class="eyebrow">Your project workspace</p><h2>Let’s get started</h2>${message?`<p class="warning">${esc(message)}</p>`:''}<form id="entryForm"><label for="fullName">Full name</label><input id="fullName" required maxlength="120" autocomplete="name" value="${teacher?'teacher':''}"><label for="className">Class</label><input id="className" ${teacher?'':'required'} maxlength="40" placeholder="For example, 8T"><label for="entryLanguage">Language support</label>${languageSelect('entryLanguage')}<label for="entryDevice">Device</label><select id="entryDevice"><option value="laptop">Laptop / desktop</option><option value="ipad">iPad / iPhone</option><option value="android">Android tablet / phone</option></select><label for="entryEditor">Coding editor</label>${editorSelect('entryEditor')}<p id="routeHint" class="caption">Choose the editor you used for your previous badge.</p><button type="submit" class="primary">Start Week 5 Project →</button></form>${existing?`<p>Saved work: <b>${esc(existing.student?.name)} · ${esc(existing.student?.cls)}</b></p><button id="resume">Resume saved work</button>`:''}<div class="actions"><button data-action="import">Import a backup</button></div><small>Your work stays on this browser. Download a backup before switching devices. Your code in MakeCode or MicroPython must also be saved in that editor.</small></section></main>`;$('#fullName').oninput=e=>{$('#className').required=!(teacher||e.target.value.trim().toLowerCase()==='teacher');};$('#entryDevice').onchange=()=>{const ipad=$('#entryDevice').value!=='laptop';$('#entryEditor option[value=micro]').disabled=ipad;if(ipad&&$('#entryEditor').value==='micro')$('#entryEditor').value='make';$('#routeHint').textContent=ipad?'Open the micro:bit app, then Create Code. Choose MakeCode Blocks or MakeCode Python.':'Choose the editor you used for your previous badge.';};const detected=/Android/i.test(navigator.userAgent)?'android':(/iPad|iPhone|iPod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1))?'ipad':'laptop';$('#entryDevice').value=detected;$('#entryDevice').onchange();$('#entryForm').onsubmit=async e=>{e.preventDefault();const name=$('#fullName').value.trim(),cls=$('#className').value.trim(),t=teacher||name.toLowerCase()==='teacher';if(!name||(!t&&!cls)){say('Enter your name and class.');return;}const old=await readSaved(L.id+(t?'.teacher':'.student'));if(old&&!confirm('Replace this mode’s saved session? Cancel to resume or export it first.'))return;teacher=t;state=blank(name,cls||'Teacher review',$('#entryLanguage').value,$('#entryDevice').value,$('#entryEditor').value);save(true);render();window.scrollTo(0,0);};if($('#resume'))$('#resume').onclick=()=>{try{state=validate(existing);render();window.scrollTo(0,0);}catch(e){landing(e.message);}};bindActions();}
function languageSelect(id){return `<select id="${id}" aria-label="Language support">${Object.entries(L.languages).map(([v,l])=>`<option value="${v}">${l.label}</option>`).join('')}</select>`;}
function editorSelect(id){return `<select id="${id}"><option value="blocks">MakeCode Blocks</option><option value="make">MakeCode Python</option><option value="micro">micro:bit MicroPython (laptop)</option></select>`;}
function render(){let slideTarget=null;if(classroomTarget){if(classroomTarget.startsWith('slide-'))slideTarget=classroomTarget;else state.current=classroomTarget;classroomTarget=null;}const c=current(),stage=L.stages.find(s=>s[0]===c.stage),same=L.cards.filter(x=>x.stage===c.stage);$('#app').innerHTML=`<header class="top"><div class="brand-mark"><span class="mark">CS</span><div>READY OR NOT?<br><small>YEAR 8 · WEEK 5 PROJECT</small></div></div><div class="toolbar"><span class="save">${saveError?'Save failed — use Backup':'Saved on this device'}</span><button data-action="backup">Backup</button><button data-action="pdf">Export PDF</button><button data-action="settings">Settings</button></div></header><div class="layout"><aside class="rail" aria-label="Learning goals and lesson progress"><div class="goals"><h2>WAGBA</h2><p class="wagba">${esc(L.goals.wagba)}</p>${['K','S','U'].map(k=>`<div class="ksu"><b>${k}</b><p><strong>${{K:'Knowledge',S:'Skills',U:'Understanding'}[k]}</strong><br>${esc(L.goals[k])}</p></div>`).join('')}</div><progress id="progress" max="${L.cards.filter(x=>!['extension','review'].includes(x.stage)).length}"></progress><p id="progressText" class="caption"></p><nav aria-label="Lesson journey">${L.stages.map(([id,title],i)=>`<button data-go="${L.cards.find(x=>x.stage===id).id}" ${id===c.stage?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')} ${title}</span><small id="stage-${id}"></small></button>`).join('')}</nav><p class="keyword-mini caption"><b>Topic</b><br>${L.goals.topic}<br><b>Keywords</b><br>input, event, variable, condition, threshold, selection, output, test, debug</p><button data-action="vocabulary">Vocabulary & support</button><p class="identity caption">${esc(state.student.name)} · ${esc(state.student.cls)}<br>${titleEditor()}</p></aside><main id="main" class="content"><div class="workspace"><div class="stage-line"><span><b>${stage[1]}</b> · ${stage[2]} · Card ${same.indexOf(c)+1} of ${same.length}</span><select id="cardJump" aria-label="Choose a card in this stage">${same.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><article class="card" id="activity" tabindex="-1"><p class="eyebrow">${c.stage==='extension'?'Further challenge · if you have time':'Smart Badge project'}</p><h1>${esc(c.title)}</h1><p class="lede">${esc(c.body)}</p>${support(c.stage)}${renderCard(c)}${c.type!=='review'?`<div class="actions"><button id="recordDone">Record task as completed</button><button id="needHelp">Record: I need help</button></div><p class="caption">Completion is your record, not an automatic mark. Leave unfinished work as pending. You can move on and return.</p>`:''}</article><footer class="nav-bottom"><button id="back" ${L.cards.indexOf(c)===0?'disabled':''}>← Back</button><small id="cardStatus">${esc(rec().status)}</small><button id="next" class="primary" ${c.type==='review'?'disabled':''}>${c.id==='extension'?'Continue to Learning Pit Stop →':'Continue →'}</button></footer></div></main></div>`;bind(c);progress();classroomChanged();if(slideTarget)window.TeacherPresentation.open(slideTarget);}
function progress(){if(!state)return;const cc=L.cards.filter(x=>!['extension','review'].includes(x.stage)),done=cc.filter(x=>state.records[x.id]?.status==='Completed').length;if($('#progress'))$('#progress').value=done;if($('#progressText'))$('#progressText').textContent=`${done} / ${cc.length} core cards completed · not a grade`;for(const [id] of L.stages){const cards=L.cards.filter(x=>x.stage===id),n=cards.filter(x=>state.records[x.id]?.status==='Completed').length;const el=$('#stage-'+id);if(el)el.textContent=n?`${n}/${cards.length}`:'';}}
function go(id,remote=false){if(!state||(!remote&&classroomLocked()))return;if(!L.cards.some(x=>x.id===id))return;snapshot();window.TeacherPresentation?.close();state.current=id;save(true);render();window.scrollTo(0,0);$('#activity').focus({preventScroll:true});}
function feedback(text,good=null){const el=$('#taskFeedback');if(el){el.className='feedback '+(good===true?'good':good===false?'improve':'');el.textContent=text;}say(text);}
function bind(c){bindActions();$$('[data-field]').forEach(el=>{const handle=()=>{rec().values[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;rec().updated=now();save();};el.addEventListener('input',handle);el.addEventListener('change',()=>{handle();snapshot(current().id,'Response changed');});});$('#cardJump').onchange=e=>go(e.target.value);$('#back').onclick=()=>go(L.cards[Math.max(0,L.cards.indexOf(c)-1)].id);$('#next').onclick=()=>{const next=L.cards[L.cards.indexOf(c)+1];if(next)go(next.id);};if($('#recordDone'))$('#recordDone').onclick=()=>setStatus('Completed');if($('#needHelp'))$('#needHelp').onclick=()=>setStatus('Needs help');
if($('#checkQuiz'))$('#checkQuiz').onclick=()=>{snapshot();const results=c.questions.map((q,i)=>{const chosen=value('q'+i),correct=chosen===q.options[q.answer];const message=!chosen?'Not answered yet. Choose an answer when ready.':(correct?'Correct. ':'Revisit this. ')+q.why;$('#qFeedback'+i).textContent=message;$('#qFeedback'+i).className='feedback '+(correct?'good':'improve');return {question:q.label,chosen:chosen||'Not answered',correct,message};});rec().checks.push({at:now(),kind:'quiz',results});save(true);say('Feedback is shown directly below each question. You may correct your answers or continue.');};
if($('#modelRun'))$('#modelRun').onclick=()=>{const raw=$('#modelPoints').value,n=Number(raw);if(!raw||!Number.isInteger(n)||n<0||n>99){say('Use a whole number from 0 to 99.');return;}const out=n>=5?'READY':'CHECK';rec().values.modelOutput=out;rec().checks.push({at:now(),kind:'model',points:n,output:out});$('#modelOutput').textContent=out;save();};
if($('#checkPredictions'))$('#checkPredictions').onclick=()=>{const message='At exactly 5, sample A displays READY because >= includes equality. Sample B displays CHECK because > excludes equality. Compare these with your predictions and your editor tests.';rec().checks.push({at:now(),kind:'predictions',values:clone(rec().values),message});snapshot();feedback(message);};
if($('#checkTests'))$('#checkTests').onclick=()=>{const results=[4,5,6].map(n=>({points:n,expected:n<5?(value('checkMessage','personalise')||'CHECK'):(value('readyMessage','personalise')||'READY'),actual:value('actual'+n)}));const missing=results.filter(x=>!x.actual.trim());const msg=missing.length?`Still to record: ${missing.map(x=>x.points).join(', ')}. You can continue and return after testing.`:'All three observations recorded. Compare each with the expected output. A teacher should review personalised icons or explanations; this does not prove the device worked.';rec().checks.push({at:now(),kind:'tests',results,message:msg});snapshot();feedback(msg);};
$$('[data-level]').forEach(b=>b.onclick=()=>{snapshot();rec().values.level=Number(b.dataset.level);save(true);render();});$$('[data-copy]').forEach(b=>b.onclick=async()=>{const code=decodeURIComponent(b.dataset.copy);try{await navigator.clipboard.writeText(code);b.textContent='Copied';}catch{modal('<h2>Select and copy this code</h2><textarea readonly>'+esc(code)+'</textarea>');}});
$$('[data-sample]').forEach(b=>b.onclick=()=>downloadSample(b.dataset.sample));$$('[data-image]').forEach(b=>b.onclick=()=>modal(`<img src="assets/images/${b.dataset.image}" alt="${esc(b.querySelector('img').alt)}">`));$$('img').forEach(im=>im.onerror=()=>{const p=im.parentElement;if(p.classList.contains('image-button')){p.classList.add('missing');p.insertAdjacentHTML('beforeend',`<span class="image-fallback">Image unavailable: ${esc(im.alt)}. Follow the written steps and code example.</span>`);p.disabled=true;}});
if($('#evidenceFile'))$('#evidenceFile').onchange=e=>addImage(e.target.files[0],c.id);if($('#pasteImage'))$('#pasteImage').onclick=async()=>{try{const items=await navigator.clipboard.read();for(const item of items){const type=item.types.find(x=>['image/png','image/jpeg','image/webp'].includes(x));if(type){await addImage(await item.getType(type),c.id);return;}}throw Error('No image found');}catch{modal('<h2>Paste or choose a screenshot</h2><p>Copy your screenshot, close this message and press Ctrl+V or Command+V on the evidence card. On iPad, use Choose File if pasting is unavailable.</p>');}};
$$('[data-caption]').forEach(el=>el.oninput=()=>{rec().images[Number(el.dataset.caption)].caption=el.value;save();});$$('[data-remove]').forEach(b=>b.onclick=()=>{if(confirm('Remove this image from the current session? Existing backups are unchanged.')){rec().images.splice(Number(b.dataset.remove),1);save(true);render();}});
}
function bindActions(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-action]').forEach(b=>b.onclick=()=>{({backup,import:()=>$('#importFile').click(),pdf:exportPDF,print:printReport,settings,vocabulary})[b.dataset.action]?.();});}
function modal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}$('#closeModal').onclick=()=>$('#modal').close();
function settings(){modal(`<h2>Your workspace</h2><p>${esc(state.student.name)} · ${esc(state.student.cls)}</p><label for="language">Language support</label>${languageSelect('language')}<label for="device">Device</label><select id="device"><option value="laptop">Laptop / desktop</option><option value="ipad">iPad / iPhone</option><option value="android">Android tablet / phone</option></select><label for="editor">Editor</label>${editorSelect('editor')}<div class="actions"><button id="applySettings" class="primary">Apply choices</button><button id="importSettings">Import backup</button><button id="returnEntry">Return to entry page</button><button id="reset">Reset saved work</button></div><p>Changing editor changes guidance only. It does not convert code saved in another editor.</p>`);$('#language').value=state.student.lang;$('#device').value=state.student.device;$('#editor').value=state.student.editor;$('#applySettings').onclick=()=>{const device=$('#device').value,editor=$('#editor').value;if(device!=='laptop'&&editor==='micro'){say('For this tablet lesson, choose MakeCode Blocks or MakeCode Python.');$('#applySettings').textContent='Choose MakeCode for your tablet';return;}state.student.lang=$('#language').value;state.student.device=device;state.student.editor=editor;save(true);$('#modal').close();render();};$('#importSettings').onclick=()=>{$('#modal').close();$('#importFile').click();};$('#returnEntry').onclick=async()=>{snapshot();await saveQueue;state=null;$('#modal').close();landing();};$('#reset').onclick=async()=>{if(!confirm('Delete this saved lesson and its images from this browser? Export a backup first if needed.'))return;clearTimeout(saveTimer);await saveQueue;await writeSaved(key(),null);state=null;$('#modal').close();landing();};}
function vocabulary(){const lang=state.student.lang,index={zh:2,ko:3,ms:4}[lang];modal(`<h2>Words that help you explain</h2><p><b>Challenge:</b> ${esc(L.goals.challenge)}</p><dl>${L.words.map(w=>`<dt><b>${w[0]}</b>${index?' · '+w[index]:''}</dt><dd>${w[1]}</dd>`).join('')}</dl><p>${esc(L.languages[lang]?.frame||'The condition is ___. It is True/False because ___. Therefore, the badge displays ___.')}</p>`);}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function filename(ext){return ('Year8_'+state.student.cls+'_'+state.student.name+'_Week5_Project').replace(/[^\p{L}\p{N}_-]/gu,'_')+'.'+ext;}
function downloadSample(which){const score=which==='A'||which==='B'?5:4,op=which==='B'?'>':'>=',code=codeSample(score,op);const isBlocks=state.student.editor==='blocks';const intro=isBlocks?'MAKECODE BLOCKS SAMPLE\n1. Create a NEW MakeCode project.\n2. Select JavaScript. Replace its starter with the source below.\n3. Choose Blocks. Run and press B.\nThis is source code, not a file to copy to the MICROBIT drive.\n\n':'';download(new Blob([intro+code],{type:'text/plain'}),`Week5_${state.student.editor}_${which}.${isBlocks?'txt':'py'}`);}
function backup(){snapshot();download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),filename('json'));say('Backup download requested. Check Downloads. It includes your uploaded images.');}
function validate(s){if(!s||s.lesson!==L.id||s.version!==1||!s.student||typeof s.student.name!=='string'||!s.student.name.trim()||typeof s.student.cls!=='string'||!s.student.cls.trim())throw Error('Choose a compatible Week 5 Project backup with a name and class.');const st=s.student,n=blank(st.name.slice(0,120),st.cls.slice(0,40),Object.hasOwn(L.languages,st.lang)?st.lang:'en',['ipad','android'].includes(st.device)?st.device:'laptop',['blocks','make','micro'].includes(st.editor)?st.editor:'blocks');if(n.student.device!=='laptop'&&n.student.editor==='micro')n.student.editor='make';n.current=L.cards.some(c=>c.id===s.current)?s.current:'read';n.started=String(s.started||now()).slice(0,60);n.updated=String(s.updated||now()).slice(0,60);n.submitted=s.submitted===true;for(const c of L.cards){const r=s.records?.[c.id];if(!r||typeof r!=='object')continue;const clean={values:{},history:[],checks:[],images:[],status:['Completed','Needs help','Not completed'].includes(r.status)?r.status:'Not completed'};for(const [k,v] of Object.entries(r.values||{})){if(!/^[a-zA-Z0-9_-]{1,60}$/.test(k)||['__proto__','constructor','prototype'].includes(k))continue;if(typeof v==='string')clean.values[k]=v.slice(0,12000);else if(typeof v==='boolean'||typeof v==='number')clean.values[k]=v;}for(const field of ['history','checks'])if(Array.isArray(r[field]))clean[field]=r[field].slice(0,1500).map(x=>{if(JSON.stringify(x).length>120000)throw Error('Oversized record in backup.');return clone(x);});for(const im of (Array.isArray(r.images)?r.images:[]).slice(0,3)){if(typeof im.data!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(im.data)||im.data.length>1500000)throw Error('Invalid evidence image in backup.');clean.images.push({data:im.data,caption:String(im.caption||'').slice(0,250),at:String(im.at||'').slice(0,60)});}n.records[c.id]=clean;}n.discussions={};for(const id of ['fact-event','fact-boundary','fact-test'])if(typeof s.discussions?.[id]==='string')n.discussions[id]=s.discussions[id].slice(0,12000);return n;}
$('#importFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>20000000)throw Error('Backup must be under 20 MB.');const n=validate(JSON.parse(await file.text()));if(!confirm('Replace the current saved work in this mode with this backup?'))return;clearTimeout(saveTimer);await saveQueue;state=n;save(true);render();}catch(err){modal('<h2>Backup not restored</h2><p>'+esc(err.message)+'</p>');}};
async function addImage(file,id){if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12000000)throw Error('Choose a PNG, JPEG or WebP below 12 MB.');const r=rec(id);if(r.images.length>=3)throw Error('Three images are already saved here. Remove one to replace it.');const img=new Image(),url=URL.createObjectURL(file);await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Could not decode image.'));img.src=url;});const scale=Math.min(1,1600/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);const data=canvas.toDataURL('image/jpeg',.85);if(data.length>1500000)throw Error('Please crop this image to the relevant code before uploading.');r.images.push({data,caption:'',at:now()});save(true);if(current().id===id)render();say('Evidence image saved. Add a caption.');}catch(e){modal('<h2>Image not added</h2><p>'+esc(e.message)+'</p>');}}
document.addEventListener('paste',e=>{if(!state||current().id!=='transfer')return;const item=[...(e.clipboardData?.items||[])].find(i=>i.type.startsWith('image/'));if(item){e.preventDefault();addImage(item.getAsFile(),'transfer');}});
function labelFor(c,k){const f=c.fields?.find(f=>f[0]===k);if(f)return f[1];if(/^q\d+$/.test(k))return c.questions?.[Number(k.slice(1))]?.label||k;if(['K','S','U'].includes(k))return L.goals[k];return ({KPhase:'Knowledge learning phase',SPhase:'Skills learning phase',UPhase:'Understanding learning phase',read:'Brief read',modelPoints:'Teaching model points',modelOutput:'Teaching model output',testEnvironment:'Test environment',physical:'Physical testing status',aWorks:'Original A feature still works',welcomeWorks:'Welcome display still works',savedCopy:'New project copy saved',originalChecked:'Original prototype checked',variableAdded:'Variable added',decisionAdded:'Button B decision added',bothPredicted:'Both outputs predicted',testReading:'Testing reading completed',level:'Extension level selected'})[k]||k.replace(/([A-Z])/g,' $1').replace(/^./,s=>s.toUpperCase());}
function readable(v){if(v==null)return 'Not supplied';if(typeof v==='boolean')return v?'Yes':'No';if(Array.isArray(v))return v.map((x,i)=>`${i+1}. ${readable(x)}`).join('\n');if(typeof v==='object')return Object.entries(v).map(([k,x])=>`${k}: ${readable(x)}`).join('\n');return String(v);}
function reportBlocks(){const blocks=[{heading:1,text:'Year 8 · Week 5 Project'},{text:'Ready or not? '+L.goals.topic},{text:state.student.name+' · '+state.student.cls},{text:'Created: '+new Date().toLocaleString()+' | Started: '+state.started},{text:'Device: '+state.student.device+' | Editor: '+titleEditor()},{text:'WAGBA: '+L.goals.wagba},...['K','S','U'].map(k=>({text:k+': '+L.goals[k]})),{text:'Keywords: input, event, variable, condition, comparison, threshold, selection, output, test, debug.'},{text:'Challenge: '+L.goals.challenge},{text:'Completion is self-reported. Open answers and practical claims need teacher review.'}];for(const c of L.cards.filter(c=>c.id!=='review')){const r=state.records[c.id],has=r&&(Object.keys(r.values).length||r.checks.length||r.images.length);if(c.stage==='extension'&&!has)continue;blocks.push({heading:2,text:L.stages.find(s=>s[0]===c.stage)[1]+' · '+c.title},{text:'Status: '+(r?.status||'Not completed')});if(!r)continue;for(const [k,v] of Object.entries(r.values))if(v!=='')blocks.push({text:labelFor(c,k)+': '+readable(v)});for(const a of r.checks)blocks.push({text:'Check at '+a.at+'\n'+readable(a.results||a.values||a.message||a)});if(r.history.length>1){blocks.push({heading:3,text:'Response history and improvements'});for(const entry of r.history)blocks.push({text:entry.at+' · '+entry.reason+'\n'+Object.entries(entry.values||{}).map(([k,v])=>labelFor(c,k)+': '+readable(v)).join('\n')});}for(const im of r.images)blocks.push({image:im.data,text:im.caption||'Student evidence image'});}for(const[id,q]of Object.entries(window.TeacherPresentation?.questions||{}))if(state.discussions?.[id])blocks.push({heading:2,text:'Class discussion'},{text:q},{text:state.discussions[id]});blocks.push({heading:2,text:'Completion summary'});for(const [id,title] of L.stages.filter(s=>s[0]!=='review')){const cs=L.cards.filter(c=>c.stage===id),n=cs.filter(c=>state.records[c.id]?.status==='Completed').length;blocks.push({text:title+': '+n+'/'+cs.length+' cards recorded as completed'});}blocks.push({text:'Teams submission: '+(state.submitted?'Student confirmed submission (not independently verified).':'Not confirmed in this app.')});return blocks;}
function reportHTML(){return `<div class="report">${reportBlocks().map(b=>b.heading?`<h${Math.min(3,b.heading+1)}>${esc(b.text)}</h${Math.min(3,b.heading+1)}>`:b.image?`<figure><img src="${b.image}" alt="Student evidence"><figcaption>${esc(b.text)}</figcaption></figure>`:`<p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(b.text)}</p>`).join('')}</div>`;}
async function printReport(){snapshot();const old=$('.print-only');if(old)old.remove();const section=document.createElement('div');section.className='print-only';section.innerHTML=reportHTML();document.body.append(section);const prev=document.title;document.title=filename('pdf').replace(/\.pdf$/,'');await Promise.all([...section.querySelectorAll('img')].map(im=>im.decode().catch(()=>{})));window.print();document.title=prev;submissionGuide('Print / Save as PDF opened. Save the file before submitting.');}
async function exportPDF(){snapshot();say('Preparing your PDF…');try{if(!window.jspdf)throw Error('PDF library unavailable');const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4'});const W=1240,H=1754,M=85,line=34,pages=[];let canvas,ctx,y;const start=()=>{canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#086b46';ctx.fillRect(M,48,W-M*2,5);ctx.fillStyle='#53635a';ctx.font='19px Arial';ctx.fillText('TENBY · COMPUTER SCIENCE · PROJECT EVIDENCE',M,35);y=105;};const end=()=>{ctx.fillStyle='#53635a';ctx.font='18px Arial';ctx.fillText((state.student.name+' · '+state.student.cls).slice(0,65),M,H-42);ctx.textAlign='right';ctx.fillText('Page '+(pages.length+1),W-M,H-42);ctx.textAlign='left';pages.push(canvas.toDataURL('image/jpeg',.94));};start();for(const b of reportBlocks()){if(b.image){const im=new Image();im.src=b.image;await im.decode();const scale=Math.min((W-2*M)/im.width,640/im.height);const h=im.height*scale;if(y+h+60>H-M){end();start();}ctx.drawImage(im,M,y,im.width*scale,h);y+=h+15;}const size=b.heading===1?36:b.heading===2?29:b.heading===3?25:23;const font=(b.heading?'bold ':'')+size+'px Arial';ctx.font=font;const rows=[];for(const paragraph of String(b.text||'').split('\n')){let row='';for(const word of paragraph.match(/\S+\s*|\s+/gu)||['']){if(ctx.measureText(row+word).width<=W-2*M){row+=word;continue;}if(row.trim())rows.push(row.trimEnd());row='';for(const char of word){if(ctx.measureText(row+char).width>W-2*M){rows.push(row);row=char;}else row+=char;}}rows.push(row.trimEnd());}if(b.heading&&y+100>H-M){end();start();}for(const row of rows){if(y+line>H-M){end();start();}ctx.font=font;ctx.fillStyle=b.heading?'#086b46':'#192620';ctx.fillText(row,M,y);y+=line;}y+=b.heading?13:17;}end();pages.forEach((page,i)=>{if(i)pdf.addPage();pdf.addImage(page,'JPEG',0,0,210,297);});pdf.save(filename('pdf'));submissionGuide('PDF download requested. Check that the file opened or downloaded successfully.');}catch(e){modal('<h2>Use the print fallback</h2><p>The direct PDF could not be created. Your work is still saved. Use Print / Save as PDF instead.</p><button id="fallbackPrint">Print / Save PDF</button>');$('#fallbackPrint').onclick=()=>{$('#modal').close();printReport();};}}
function submissionGuide(message){modal(`<h2>Next: submit your evidence</h2><p>${esc(message)}</p><h3>Find your PDF</h3><p><b>Laptop:</b> check your browser’s Downloads menu (often top right) or your Downloads folder.</p><p><b>iPad / iPhone:</b> open the download in Safari. If it opens as a preview, use Share → Save to Files and choose a folder. If using Print, expand the print preview with two fingers, then Share → Save to Files. Menu placement varies by browser.</p><h3>Upload to Microsoft Teams</h3><ol><li>Open your Computer Science class. In Classwork, open <b>Week 5 Project</b>, or the assignment your teacher names.</li><li>Open the assignment and choose <b>Add work / Attach</b>. Choose the PDF from Downloads or Files.</li><li>Check the attached file shows your name, class and evidence. Upload the PDF, not a screenshot.</li><li>Select <b>Turn in</b> and check the confirmation.</li></ol><label class="option submission-check"><input type="checkbox" id="submittedCheck" ${state.submitted?'checked':''}><span>I have attached my PDF and clicked Turn in in Teams.</span></label><button id="confirmSubmission" class="primary">Confirm my submission</button><p class="caption">This is your confirmation. The app cannot access or verify Teams.</p>`);$('#confirmSubmission').onclick=()=>{if(!$('#submittedCheck').checked){say('Only confirm after you have submitted in Teams.');return;}state.submitted=true;state.submittedAt=now();save(true);$('#modal').close();go('review');};}
window.addEventListener('pagehide',()=>{if(state)save(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state)save(true);});landing();
})();
